/*
 * tokens.h -- Token codes for MiniLang.
 *
 * Since Phase 2, the token codes are generated by Bison from the %token
 * declarations in parser.y and written to build/parser.h. The codes start
 * at 258: values 0-255 are reserved for single characters, 256/257 are
 * Bison's internal "error" and "undefined" tokens, and 0 (YYEOF) means end
 * of input.
 */
#ifndef TOKENS_H
#define TOKENS_H

#include "parser.h"   /* enum yytokentype: KW_INT, IDENT, OP_PLUS, ... */

/* Returns a printable name for a token code, e.g. "KW_INT" or "OP_PLUS". */
const char *token_name(int tok);

#endif /* TOKENS_H */
